"Auf dem Bildschirm der Fotobox und auf dem zweiten Bildschirm (Fernseher/Beamer) wird sie Strich für Strich gezeichnet und eingefärbt.": "Fotoğraf kabininin ekranında ve ikinci ekranda (TV/projektör) çizgi çizgi çizilir ve boyanır.",
"Auf dem Fotobox-PC installieren": "Fotoğraf kabini bilgisayarına kur",
"Auf dem Startbildschirm der Fotobox (unten rechts) und auf der Karikaturen-Wand (zweiter Bildschirm) stehen ein QR-Code und ein Code. Gäste schicken damit vom eigenen Handy ein Selfie mit Gruß und Namen – ohne App. Die Fotobox zeichnet, zeigt und druckt jede Karikatur.": "Fotoğraf kabininin başlangıç ekranında (sağ altta) ve karikatür duvarında (ikinci ekran) bir QR kod ve bir kod bulunur. Misafirler bununla kendi telefonlarından selamlı ve isimli bir selfie gönderir – uygulama olmadan. Fotoğraf kabini her karikatürü çizer, gösterir ve basar.",
"Auf dem Startbildschirm der Fotobox erscheint eine gut sichtbare Karte mit QR-Code. Gäste scannen sie, nehmen mit ihrem eigenen Handy eine Videonachricht auf (bis 30 Sekunden) und schicken sie ab – die Fotobox bleibt dabei frei für die nächsten Gäste.": "Fotoğraf kabininin başlangıç ekranında QR kodlu, iyi görünen bir kart çıkar. Misafirler onu tarar, kendi telefonlarıyla bir video mesaj kaydeder (en fazla 30 saniye) ve gönderir – fotoğraf kabini bu sırada sonraki misafirler için boş kalır.",
"Auf dem Startbildschirm erscheint eine Karte mit QR-Code. Gäste scannen sie, nehmen mit ihrem eigenen Handy eine Videonachricht auf (bis 30 Sekunden) und schicken sie ab – die Fotobox bleibt frei für die nächsten Gäste. Die Videos erscheinen in der Galerie dieses Ereignisses.": "Başlangıç ekranında QR kodlu bir kart görünür. Misafirler kodu tarar, kendi telefonlarıyla bir video mesaj kaydeder (30 saniyeye kadar) ve gönderir – fotoğraf kabini sonraki misafirler için boş kalır. Videolar bu etkinliğin galerisinde görünür.",
"Auf dem Startbildschirm zeigen": "Başlangıç ekranında göster",
"Auf dem Zweitdrucker drucken": "İkinci yazıcıda yazdır",
"Auf der Download-Seite und in der Galerie sehen die Gäste dein Logo, deinen Text und deinen Link.": "İndirme sayfasında ve galeride misafirler senin logonu, metnini ve bağlantını görür.",
"Auf der Karikaturen-Wand (zweiter Bildschirm der Fotobox) stehen ein QR-Code und ein Code. Gäste schicken damit vom eigenen Handy ein Selfie mit Gruß und Namen – ohne App. Die Fotobox zeichnet, zeigt und druckt jede Karikatur.": "Karikatür duvarında (fotoğraf kabininin ikinci ekranı) bir QR kod ve bir kod bulunur. Misafirler bununla kendi telefonlarından selamlı ve isimli bir selfie gönderir – uygulama gerekmez. Fotoğraf kabini her karikatürü çizer, gösterir ve yazdırır.",
"Auf der Startseite und in den anderen Menü-Seiten gibt die Fotobox die Canon frei – dann gehen Menü und Tasten an der Kamera selbst (kein „Beschäftigt“). Hier in den Kameraeinstellungen und beim Fotografieren übernimmt die Fotobox die Kamera wieder (2–5 Sekunden).": "Başlangıç sayfasında ve diğer menü sayfalarında fotoğraf kabini Canon'u serbest bırakır – o zaman kameranın kendi menüsü ve tuşları çalışır (“Meşgul” yok). Burada, kamera ayarlarında ve fotoğraf çekerken fotoğraf kabini kamerayı yeniden devralır (2–5 saniye).",
