"AUS": "KAPALI",
"Aus = alle Fotos bekommen automatisch den Standard-Stil.": "Kapalı = tüm fotoğraflar otomatik olarak varsayılan stili alır.",
"Aus = keine Abfrage an der Fotobox. Das Foto wird trotzdem an den KI-Dienst (xAI, USA) übertragen – die Einwilligung regelst du dann selbst, zum Beispiel im Vertrag mit deinem Kunden oder per Aushang an der Fotobox.": "Kapalı = fotoğraf kabininde soru sorulmaz. Fotoğraf yine de yapay zekâ hizmetine (xAI, ABD) gönderilir – onayı kendin düzenlersin, örneğin müşterinle yaptığın sözleşmede veya fotoğraf kabinindeki bir duyuruyla.",
"Aus = nur Fotos direkt an der Fotobox.": "Kapalı = yalnızca doğrudan fotoğraf kabininde çekilen fotoğraflar.",
"Aus dem Dashboard": "Panelden",
"Aus den Fotos einer Sitzung entsteht zusätzlich ein GIF – es landet auch in der Galerie.": "Bir seansın fotoğraflarından ek olarak bir GIF oluşur – o da galeriye eklenir.",
"Aus den Fotos einer Sitzung wird zusätzlich ein animiertes GIF gespeichert.": "Bir oturumun fotoğraflarından ayrıca animasyonlu bir GIF kaydedilir.",
