"Aus vielen Gästefotos entsteht ein großes Bild – live auf dem Fernseher oder als Klebewand mit nummerierter Tafel.": "Birçok misafir fotoğrafından büyük bir resim oluşur – televizyonda canlı veya numaralı panolu yapıştırma duvarı olarak.",
"Aus vielen kleinen Gästefotos entsteht ein großes Bild – live auf einem Fernseher oder Beamer und/oder als Klebewand: Jede Kachel wird mit ihrer Feldnummer (z. B. „C7“) gedruckt und auf die vorher gedruckte Tafel geklebt.": "Çok sayıda küçük misafir fotoğrafından büyük bir resim oluşur – canlı olarak bir TV veya projeksiyonda ve/veya yapıştırma duvarı olarak: Her parça alan numarasıyla (ör. “C7”) basılır ve önceden basılmış panoya yapıştırılır.",
"Aus vielen kleinen Gästefotos entsteht ein großes Bild – live auf einem Fernseher oder Beamer und/oder als Klebewand: Jede Kachel wird mit ihrer Feldnummer (z. B. „C7“) gedruckt und auf die vorher gedruckte Tafel geklebt. Diese Einstellungen gelten für das ganze Ereignis und sind auch im Dashboard einstellbar.": "Çok sayıda küçük misafir fotoğrafından büyük bir resim oluşur – canlı olarak bir TV veya projeksiyonda ve/veya yapıştırma duvarı olarak: Her parça alan numarasıyla (ör. “C7”) basılır ve önceden basılmış panoya yapıştırılır. Bu ayarlar tüm etkinlik için geçerlidir ve panelden de yapılabilir.",
"Aus vielen kleinen Gästefotos entsteht ein großes Bild – live auf einem Fernseher oder Beamer und/oder als Klebewand: Jede Kachel wird mit ihrer Feldnummer (z. B. „C7“) gedruckt und auf die vorher gedruckte Tafel geklebt. {x}": "Çok sayıda küçük misafir fotoğrafından büyük bir resim oluşur – canlı olarak bir TV veya projeksiyonda ve/veya yapıştırma duvarı olarak: Her parça alan numarasıyla (ör. “C7”) basılır ve önceden basılmış panoya yapıştırılır. {x}",
