"Bei bestimmten Ereignissen ruft die Fotobox eine Anwendung auf, um sie zu benachrichtigen. Nützlich für Licht-Steuerung und eigene Programme. Die Anwendung erhält als Parameter die Art des Ereignisses (session_start, countdown_start, capture_start, processing_start, sharing_screen, printing, session_end).": "Belirli olaylarda kabin, bildirim için bir uygulamayı çağırır. Işık kontrolü ve kendi programların için kullanışlıdır. Uygulama, olay türünü parametre olarak alır (session_start, countdown_start, capture_start, processing_start, sharing_screen, printing, session_end).",
"Bei Bewegungserkennung aufnehmen": "Hareket algılanınca kaydet",
"Bei der Canon in den Kameraeinstellungen. Für das Livebild kannst du eigene, hellere Werte setzen. „Testfoto aufnehmen“ zeigt das Ergebnis.": "Canon için kamera ayarlarında. Canlı görüntü için kendi, daha parlak değerlerini ayarlayabilirsin. „Test fotoğrafı çek“ sonucu gösterir.",
"Bei mehreren Dateien zufällig eine abspielen": "Birden fazla dosya varsa rastgele birini oynat",
