"Bei Stripe ist keine Zahlungsart hinterlegt – die nächste Rechnung mit Betrag kann nicht abgebucht werden. Bitte den Kunden bitten, im Shop unter „Abo & Rechnungen verwalten“ eine Zahlungsart einzutragen.": "Stripe’ta kayıtlı ödeme yöntemi yok – tutarı olan bir sonraki fatura tahsil edilemez. Lütfen müşteriden mağazada “Abonelik ve faturaları yönet” altında bir ödeme yöntemi eklemesini isteyin.",
"Bei Stripe läuft kein Abo dieses Kunden – es gibt nichts anzupassen.": "Bu müşterinin Stripe’da aktif aboneliği yok – ayarlanacak bir şey yok.",
"Bei Stripe war schon alles richtig.": "Stripe’da her şey zaten doğruydu.",
"Bei Stripe übernehmen": "Stripe’da uygula",
"Bei Stripe übernommen – gilt ab der nächsten Rechnung des Kunden.": "Stripe’da uygulandı – müşterinin bir sonraki faturasından itibaren geçerli.",
"Bei {x} von {x} laufenden Abos hat Stripe es nicht übernommen{x}.": "{x}/{x} aktif abonelikte Stripe bunu uygulamadı{x}.",
"Beim Antippen eines Textfelds (z. B. Name des Ereignisses) erscheint die Windows-Tastatur – auch wenn ein Buzzer oder Funk-Empfänger angeschlossen ist. Kommt sie trotzdem nicht, hilft der Knopf „⌨ Tastatur“ unten rechts. Gilt ab dem nächsten Programmstart.": "Bir metin alanına dokunduğunda (örn. etkinlik adı) Windows klavyesi açılır – bir buzzer veya kablosuz alıcı bağlı olsa bile. Yine de gelmezse sağ alttaki „⌨ Klavye“ düğmesi yardımcı olur. Programın bir sonraki açılışından itibaren geçerli.",
"Beim Antippen eines Textfelds blendet die Fotobox die Windows-Tastatur ein. Kommt sie nicht, hilft der Knopf „⌨ Tastatur“ unten rechts.": "Bir metin alanına dokunduğunda fotoğraf kabini Windows klavyesini açar. Gelmezse sağ alttaki „⌨ Klavye“ düğmesi yardımcı olur.",
"Beim Ausschalten bekommt der Kunde genau seinen Stand von vorher zurück – auch die Zahl der Fotoboxen (eine während VIP geänderte Zahl gilt nur für die VIP-Zeit).": "Kapatıldığında müşteri tam olarak önceki durumuna döner – fotoğraf kabini sayısı da (VIP sırasında değiştirilen sayı yalnızca VIP süresi için geçerlidir).",
"Beim nächsten Anmelden im Dashboard legt er ein eigenes Passwort fest. Das Einmal-Passwort wird nur jetzt angezeigt.": "Kontrol paneline bir sonraki girişte kendi şifresini belirler. Tek seferlik şifre yalnızca şimdi gösterilir.",
