"Daten aus dem Gäste-Formular der FotoBox (Einverständnis, Name, E-Mail …). Bitte DSGVO beachten: nur für den angegebenen Zweck nutzen und nach dem Event löschen.": "Kabin misafir formundan gelen veriler (onay, ad, e-posta …). Lütfen KVKK/GDPR'ye uyun: yalnızca belirtilen amaçla kullanın ve etkinlikten sonra silin.",
