"Datenschutz: Du bist für die Daten deiner Kunden verantwortlich, wir verarbeiten sie in deinem Auftrag (AVV). Ergänze in deiner Datenschutzerklärung einen Absatz zu BoothDesigner – eine Vorlage bekommst du von uns.": "Veri koruma: Müşterilerinin verileri için veri sorumlusu sensin; biz bu verileri senin adına işliyoruz (AVV). Gizlilik politikana BoothDesigner hakkında bir paragraf ekle – şablonunu bizden alırsın.",
