"Dein Konto ist das Betreiber-Konto. Damit niemand allein mit deinem Passwort an die Daten deiner Kunden kommt, brauchst du für den Admin-Bereich ab jetzt zusätzlich einen Code von deinem Handy.": "Hesabın işletmeci hesabı. Kimse yalnızca şifrenle müşterilerinin verilerine ulaşamasın diye, yönetim alanı için artık ek olarak telefonundan bir kod gerekiyor.",
