"Dein Test bzw. Abo ist abgelaufen. Deine Einstellungen und Einsendungen bleiben erhalten, bis du weitermachst.": "Deneme süren veya aboneliğin sona erdi. Devam edene kadar ayarların ve gönderimlerin saklanır.",
"Dein Test läuft 1 Monat: Fotomosaik, Live-Karikatur und Videonachricht sind freigeschaltet, dazu 10 KI-Credits. Melde dich in der Fotobox mit diesem Konto an.": "Denemen 1 ay sürer: Fotoğraf mozaiği, canlı karikatür ve video mesajı açıldı, ayrıca 10 yapay zekâ kredisi. Fotoğraf kabininde bu hesapla giriş yap.",
"Dein Test läuft 1 Monat: Fotomosaik, Live-Karikatur und Videonachricht sind freigeschaltet, dazu 20 KI-Credits. Melde dich in der Fotobox mit diesem Konto an.": "Denemen 1 ay sürer: Fotoğraf mozaiği, canlı karikatür ve video mesajı açıldı, ayrıca 20 yapay zekâ kredisi. Fotoğraf kabininde bu hesapla giriş yap.",
"Dein Test läuft 30 Tage: alle Fotobox-Funktionen und alle Zusatzfunktionen sind freigeschaltet. Melde dich in der Fotobox mit diesem Konto an.": "Denemen 30 gün sürüyor: tüm fotoğraf kabini özellikleri ve tüm ek özellikler kullanıma açık. Fotoğraf kabininde bu hesapla giriş yap.",
"Dein Text": "Metnin",
