"Deine Anmeldung ist abgelaufen. Bitte melde dich neu an.": "Oturumunun süresi doldu. Lütfen yeniden giriş yap.",
"Deine FotoBox": "Fotoğraf kabinin",
"Deine Fotos sind im Mosaik!": "Fotoğrafların mozaikte!",
"Deine gesammelten Stile mit Bild – für jedes Event. Antippen übernimmt den Stil in dieses Event, ohne Credits.": "Görselli kayıtlı stillerin – her etkinlik için. Dokunarak stili bu etkinliğe kredisiz ekle.",
"Deine gesammelten Stile mit Bild – für jedes Event. Antippen übernimmt den Stil in dieses Event, ohne Credits. ✎ = Text ändern und neu generieren.": "Görselli topladığın stiller – her etkinlik için. Dokununca stil bu etkinliğe eklenir, kredi harcanmaz. ✎ = metni değiştir ve yeniden oluştur.",
"Deine gesammelten Stile mit Bild – für jedes Event. Antippen übernimmt den Stil in dieses Event, ohne Credits. ✎ = Text ändern und neu generieren. Die Bilder zeigen immer unser Testpaar.": "Görselli topladığın stiller – her etkinlik için. Dokunmak stili bu etkinliğe kredisiz ekler. ✎ = metni değiştir ve yeniden oluştur. Görseller her zaman test çiftimizi gösterir.",
"Deine Kachel wird gedruckt – klebe sie an der Mosaik-Wand auf das Feld mit dieser Nummer.": "Parçan yazdırılıyor – mozaik duvarında bu numaralı alana yapıştır.",
"Deine Kacheln werden gedruckt – klebe sie an der Mosaik-Wand auf die Felder mit diesen Nummern.": "Parçaların yazdırılıyor – mozaik duvarında bu numaralı alanlara yapıştır.",
"Deine Karikatur ist da – speichern, teilen, Erinnerung behalten.": "Karikatürün hazır – kaydet, paylaş, anıyı sakla.",
"Deine kostenlose Lizenz ist bereit. Melde dich in der Fotobox mit diesem Konto an.": "Ücretsiz lisansın hazır. Fotoğraf kabininde bu hesapla oturum aç.",
"Deine Kunden gestalten ihr Fotolayout selbst": "Müşterilerin fotoğraf düzenlerini kendileri tasarlar",
"Deine Testlizenz läuft 14 Tage. Melde dich in der Fotobox mit diesem Konto an – oder trage dort den Schlüssel ein.": "Deneme lisansın 14 gün geçerli. Kabinde bu hesapla giriş yap – veya anahtarı orada gir.",
