"Eingeschaltet. Für den Admin-Bereich brauchst du nach dem Passwort den Code aus der Authenticator-App – das prüft auch der Server, nicht nur diese Seite. Deine eigene Fotobox meldet sich weiter nur mit dem Passwort an: Sie hat damit keine Admin-Rechte, nur deine eigenen Events.": "Açık. Yönetim alanı için şifreden sonra Authenticator uygulamasındaki kod gerekir – bunu sadece bu sayfa değil, sunucu da kontrol eder. Kendi fotoğraf kabinin yine sadece şifreyle giriş yapar: yönetici yetkisi yoktur, yalnızca kendi etkinliklerin.",
