"Fotos, die nach einem Ereignis noch in der Windows-Warteschlange des Druckers hängen (z. B. Papier leer oder Drucker aus), würden sonst beim nächsten Einschalten gedruckt. Die Fotobox fragt deshalb beim Beenden, ob sie gelöscht werden sollen, und löscht Reste beim Wechsel zum nächsten Ereignis und beim Start (älter als 3 Stunden). Andere Dokumente bleiben. Von Hand: Einstellungen → Drucker → „Jetzt alle wartenden Fotos löschen“. Fotos im Speicher des Druckers selbst: Drucker aus- und einschalten.": "Bir etkinlikten sonra yazıcının Windows kuyruğunda kalan fotoğraflar (ör. kâğıt bitti veya yazıcı kapalı) aksi halde bir sonraki açılışta basılır. Bu yüzden fotoğraf kabini kapatılırken silinip silinmeyeceğini sorar, bir sonraki etkinliğe geçerken ve açılışta (3 saatten eski) kalanları siler. Diğer belgeler kalır. Elle: Ayarlar → Yazıcı → „Bekleyen tüm fotoğrafları şimdi sil“. Yazıcının kendi belleğindeki fotoğraflar için: yazıcıyı kapatıp aç.",
"Fotoseite ansehen": "Fotoğraf sayfasını görüntüle",
"Fotostreifen": "Fotoğraf şeridi",
"Fotostreifen (2×6): Den Schnitt „2 inch cut“ schaltet die Software bei jedem Streifen-Druck selbst ein und bei allen anderen Drucken aus – im Treiber muss dafür nichts umgestellt werden und ein zweiter Drucker ist nicht nötig. Das passende Papierformat wählt sie ebenfalls selbst, wenn das eingestellte nicht zum Layout passt.": "Fotoğraf şeritleri (2×6): Yazılım “2 inch cut” kesimini her şerit baskısında açar, diğer tüm baskılarda kapatır – sürücüde bir şey değiştirmek gerekmez ve ikinci yazıcıya ihtiyaç yoktur. Ayarlı kâğıt düzene uymazsa uygun kâğıt boyutunu da kendisi seçer.",
"Fotostreifen 2×6": "Fotoğraf şeridi 2×6",
