"für alle Software-Kunden freigegeben (gelb) – antippen zum Zurücknehmen. Neu gespeicherte Stile sind sofort freigegeben. Deine Kunden sehen sie unter „Stile von Photobox Memories“.": "tüm yazılım müşterileriyle paylaşıldı (sarı) – geri almak için dokun. Yeni kaydedilen stiller hemen paylaşılır. Müşterilerin bunları „Photobox Memories stilleri“ altında görür.",
