"Für das Ereignis „{x}“ sind KI-Porträts im Dashboard ausgeschaltet. Entweder im Dashboard bei genau diesem Ereignis unter „KI-Porträts“ einschalten und eine Vorgabe speichern – oder hier das Ereignis wählen, bei dem du KI eingerichtet hast.": "“{x}” etkinliği için panelde yapay zekâ portreleri kapalı. Ya panelde tam bu etkinlik için “Yapay zekâ portreleri” altında açıp bir varsayılan kaydedin ya da burada yapay zekâyı kurduğunuz etkinliği seçin.",
"Für das Ereignis „{x}“ werden zurzeit keine Fotos hochgeladen.": "“{x}” etkinliği için şu anda fotoğraf yüklenmiyor.",
"Für das Mosaik ist noch kein Hauptbild eingestellt.": "Mozaik için henüz ana görsel ayarlanmadı.",
"Für dein Konto ist schon alles kostenlos (VIP). Du musst nichts buchen – für weitere Fotoboxen bitte bei Photobox Memories melden.": "Hesabınız için her şey zaten ücretsiz (VIP). Hiçbir şey satın almanız gerekmiyor – daha fazla fotoğraf kabini için lütfen Photobox Memories ile iletişime geçin.",
"Für den Fotobox-PC mit Windows.": "Windows’lu fotoğraf kabini bilgisayarı için.",
"Für den Shop brauchst du Links zu AGB, Datenschutz und Impressum.": "Mağaza için genel şartlar, gizlilik politikası ve künye bağlantılarına ihtiyacın var.",
"Für die Slideshow bitte zuerst unter „Allgemein“ anmelden und ein Ereignis wählen.": "Slayt gösterisi için lütfen önce “Genel” altında giriş yapın ve bir etkinlik seçin.",
"Für die Slideshow bitte zuerst „Freigabe von Links“ einschalten.": "Slayt gösterisi için lütfen önce “Bağlantı paylaşımı”nı açın.",
"Für die Videonachricht bitte zuerst unter „Allgemein“ mit deinem Konto anmelden und ein Ereignis wählen.": "Video mesaj için önce „Genel“ altında hesabınla oturum aç ve bir etkinlik seç.",
"Für diese E-Mail-Adresse gibt es schon ein Konto – bitte anmelden.": "Bu e-posta adresi için zaten bir hesap var – lütfen giriş yap.",
"Für dieses Ereignis wurden keine Shares gefunden.": "Bu etkinlik için paylaşım bulunamadı.",
"Für dieses Event sind keine weiteren Videonachrichten möglich.": "Bu etkinlik için başka video mesaj gönderilemez.",
"Für dieses Konto gibt es schon eine Lizenz oder einen Test.": "Bu hesabın zaten bir lisansı veya denemesi var.",
"Für ein eigenes Bild bitte zuerst unter „Allgemein“ mit deinem Konto anmelden und ein Ereignis wählen.": "Kendi resmin için önce „Genel“ altında hesabınla oturum aç ve bir etkinlik seç.",
