"Gib einen PIN ein (am besten nur Ziffern) und speichere. Er wird gebraucht, um das laufende Ereignis zu verlassen, die Sperre aufzuheben, den Vollbildmodus zu verlassen und das Programm zu schließen. Gesperrt wird mit „Sperren“ oben im Menü oder mit „Ereignis starten“.": "Bir PIN girin (tercihen yalnızca rakam) ve kaydedin. Çalışan etkinlikten çıkmak, kilidi açmak, tam ekrandan çıkmak ve programı kapatmak için gerekir. Kilitleme, menünün üstündeki “Kilitle” veya “Etkinliği başlat” ile yapılır.",
