"Gilt für alle Käufe des Kunden (Fotobox, Zusatzfunktionen und BoothDesigner) über Stripe. 0 % = kein Rabatt. Soll er gar nichts zahlen, ist VIP einfacher.{x}{x}": "Müşterinin Stripe üzerinden yaptığı tüm satın alımlar için geçerlidir (fotoğraf kabini, ek işlevler ve BoothDesigner). 0 % = indirim yok. Hiç ödeme yapmaması gerekiyorsa VIP daha kolaydır.{x}{x}",
"Gilt für alles, was Gäste sehen: Startbildschirm, Auswahl, Countdown, Teilen, Drucken, Formular und die Seite zum Herunterladen hinter dem QR-Code. Texte, die Sie selbst geändert haben, bleiben so, wie Sie sie geschrieben haben.": "Misafirlerin gördüğü her şey için geçerlidir: başlangıç ekranı, seçim, geri sayım, paylaşım, yazdırma, form ve QR kodunun arkasındaki indirme sayfası. Kendi değiştirdiğiniz metinler, yazdığınız gibi kalır.",
