"Gäste bestellen auf ihrer Fotoseite (QR-Code an der Fotobox) ihr Foto als Poster, Leinwand, Tasse und mehr. Bezahlt wird über Stripe, gedruckt und verschickt wird von Gelato. Vorerst nur für die Fotos deiner eigenen Fotoboxen.": "Misafirler fotoğraf sayfalarında (kabindeki QR kod) fotoğraflarını poster, kanvas, kupa ve daha fazlası olarak sipariş eder. Ödeme Stripe ile yapılır, baskı ve gönderimi Gelato yapar. Şimdilik yalnızca kendi kabinlerinin fotoğrafları için.",
"Gäste bestellen auf ihrer Fotoseite (QR-Code an der Fotobox) ihr Foto als Tasse, Mauspad, Magnet und mehr. Bezahlt wird über Stripe, gedruckt und verschickt wird von Gelato oder Printful. Vorerst nur für die Fotos deiner eigenen Fotoboxen.": "Misafirler fotoğraf sayfalarında (kabindeki QR kod) fotoğraflarını kupa, mouse pad, magnet ve daha fazlası olarak sipariş eder. Ödeme Stripe ile yapılır, baskı ve gönderimi Gelato veya Printful yapar. Şimdilik yalnızca kendi kabinlerinin fotoğrafları için.",
"Gäste bestätigen vor der Aufnahme einen Text – sonst wird die Sitzung abgebrochen.": "Misafirler çekimden önce bir metni onaylar – aksi halde seans iptal edilir.",
"Gäste dürfen nach der Aufnahme selbst ein Design wählen (Häkchen „Gäste“ an den Vorlagen)": "Misafirler çekimden sonra kendileri bir tasarım seçebilir (şablonlarda “Misafirler” işareti)",
"Gäste können die Aufnahme verwerfen und wiederholen": "Misafirler çekimi silip tekrarlayabilir",
"Gäste können die einzelnen Originalfotos ansehen und teilen": "Misafirler tek tek orijinal fotoğrafları görüp paylaşabilir",
"Gäste können ihr Foto auch ohne KI-Stil behalten": "Misafirler fotoğraflarını yapay zekâ stili olmadan da tutabilir",
"Gäste müssen dieses Passwort eingeben, um das Ereignis anzusehen. Lassen Sie das Feld leer, um das Passwort zu deaktivieren.": "Misafirlerin etkinliği görmek için bu şifreyi girmesi gerekir. Şifreyi kapatmak için alanı boş bırakın.",
"Gäste scannen den QR-Code und haben das Foto sofort auf dem Handy. Dafür muss das Hochladen in die Online-Galerie eingeschaltet sein.": "Misafirler QR kodu tarar ve fotoğraf hemen telefonlarında olur. Bunun için çevrimiçi galeriye yükleme açık olmalı.",
"Gäste scannen den QR-Code und haben das Foto sofort auf dem Handy. Dafür muss die Fotobox angemeldet, ein Ereignis aus dem Dashboard gewählt und das Hochladen in die Online-Galerie eingeschaltet sein – sonst funktioniert der QR-Code nur im selben WLAN (gelber Hinweis auf dem Startbildschirm).": "Misafirler QR kodu tarar ve fotoğraf anında telefonlarında olur. Bunun için fotoğraf kabininin oturum açmış, panelden bir etkinliğin seçilmiş ve çevrim içi galeriye yüklemenin açık olması gerekir – aksi hâlde QR kod yalnızca aynı Wi-Fi ağında çalışır (başlangıç ekranında sarı uyarı).",
"Gäste scannen den QR-Code und hinterlassen mit ihrem Handy eine Videonachricht. Überschrift und Hinweis stellst du unter „Videonachricht“ ein.": "Misafirler QR kodu tarar ve telefonlarıyla bir video mesaj bırakır. Başlığı ve notu „Video mesaj“ altında ayarlarsınız.",
"Gäste scannen einen QR-Code auf dem Startbildschirm der Fotobox und hinterlassen mit ihrem eigenen Handy eine Videonachricht (bis 30 Sekunden). Die Videos erscheinen in der Galerie des Events.": "Misafirler fotoğraf kabininin başlangıç ekranındaki QR kodu tarar ve kendi telefonlarıyla bir video mesaj bırakır (en fazla 30 saniye). Videolar etkinlik galerisinde görünür.",
"Gäste scannen einen QR-Code und hinterlassen mit dem eigenen Handy eine Videonachricht. Vorher sehen sie auf Wunsch dein Begrüßungsvideo.": "Misafirler bir QR kodu tarar ve kendi telefonlarıyla bir video mesaj bırakır. İstersen önce senin karşılama videonu görürler.",
"Gäste schicken Selfies vom Handy": "Misafirler telefondan selfie gönderir",
"Gäste sehen nach dem Scannen zuerst dieses Video – z. B. das Brautpaar sagt Hallo und bittet um eine Nachricht – und nehmen danach ihre eigene Videonachricht auf. Ohne Video geht es direkt zur Aufnahme.": "Misafirler taradıktan sonra önce bu videoyu görür – örn. gelin ve damat merhaba der ve bir mesaj ister – ardından kendi video mesajlarını kaydeder. Video yoksa doğrudan kayda geçilir.",
"Gäste sehen nach dem Scannen zuerst dieses Video – z. B. das Brautpaar sagt Hallo und bittet um eine Nachricht – und nehmen danach ihre eigene Videonachricht auf. Ohne Video geht es direkt zur Aufnahme. Auch im Online-Dashboard änderbar.": "Misafirler taradıktan sonra önce bu videoyu görür – örn. gelin ve damat merhaba der ve bir mesaj ister – ardından kendi video mesajlarını kaydeder. Video yoksa doğrudan kayda geçilir. Çevrimiçi panelden de değiştirilebilir.",
"Gäste sehen sich beim Countdown im Fotolayout – so wie das fertige Foto. Aus: nur das Kamerabild.": "Misafirler geri sayım sırasında kendilerini fotoğraf düzeninde görür – tıpkı bitmiş fotoğraf gibi. Kapalı: yalnızca kamera görüntüsü.",
"Gäste tippen auf eine Flagge und sehen alles in ihrer Sprache. Nach jeder Sitzung springt die Fotobox zurück zur Standardsprache.": "Misafirler bir bayrağa dokunur ve her şeyi kendi dillerinde görür. Her oturumdan sonra kabin varsayılan dile döner.",
"Gäste verzieren ihr Foto mit Aufklebern oder malen darauf.": "Misafirler fotoğraflarını çıkartmalarla süsler veya üzerine çizer.",
"Gäste vor dem KI-Porträt um Zustimmung bitten": "Yapay zekâ portresinden önce misafirlerden onay iste",
"Gäste werden zu Filmstars, Superhelden oder Kunstwerken. Stile auswählen, Zustimmung und Texte einstellen.": "Misafirler film yıldızına, süper kahramana veya sanat eserine dönüşür. Stilleri seç, onayı ve metinleri ayarla.",
