"Hängen nach einem Ereignis noch Fotos in der Warteschlange (z. B. Papier leer oder Drucker aus), fragt die Fotobox beim Beenden, ob sie gelöscht werden sollen, und löscht Reste beim Wechsel zum nächsten Ereignis (aus dem Dashboard) und beim Start (wenn älter als 3 Stunden) – damit nichts unnötig gedruckt wird. Andere Dokumente bleiben. Fotos, die schon im Speicher des Druckers liegen, druckt er trotzdem – dann den Drucker einmal aus- und wieder einschalten.": "Bir etkinlikten sonra kuyrukta hâlâ fotoğraf kalırsa (ör. kâğıt bitti veya yazıcı kapalı), fotoğraf kabini kapatılırken silinip silinmeyeceğini sorar, bir sonraki etkinliğe geçerken (kontrol panelinden) ve açılışta (3 saatten eskiyse) kalanları siler – böylece gereksiz baskı olmaz. Diğer belgeler kalır. Yazıcının belleğindeki fotoğraflar yine de basılır – o zaman yazıcıyı bir kez kapatıp aç.",
"Häufig gesucht": "Sık arananlar",
"höchstens {x}": "en fazla {x}",
"Höchstzahl an Ausdrucken für das ganze Ereignis und pro Gast. Das Restlimit kann unter dem Drucken-Knopf stehen.": "Tüm etkinlik ve misafir başına en fazla baskı sayısı. Kalan limit yazdır düğmesinin altında gösterilebilir.",
"Höchstzahl ändern": "Üst sınırı değiştir",
"Höhe": "Yükseklik",
"Ich bin einverstanden, dass mein Foto von einer KI zu einer Karikatur gezeichnet und auf dem Bildschirm, im Ausdruck und in der Online-Galerie des Events gezeigt wird.": "Fotoğrafımın bir yapay zekâ tarafından karikatüre çizilmesini ve ekranda, baskıda ve etkinliğin çevrimiçi galerisinde gösterilmesini kabul ediyorum.",
"Ich bin einverstanden, dass mein Video in der Online-Galerie dieses Events gezeigt wird.": "Videomun bu etkinliğin çevrim içi galerisinde gösterilmesini kabul ediyorum.",
"Ich bin einverstanden, dass meine Fotos gespeichert und für dieses Event verwendet werden.": "Fotoğraflarımın kaydedilmesini ve bu etkinlik için kullanılmasını kabul ediyorum.",
"Ich bin einverstanden, dass meine Fotos mit dem Event-Prompt an": "Fotoğraflarımın etkinlik istemiyle birlikte şuraya gönderilmesini kabul ediyorum:",
"Ich darf dieses Foto verwenden und stimme zu, dass Foto und Beschreibung zur Bilderstellung an": "Bu fotoğrafı kullanma hakkım var ve fotoğraf ile açıklamanın görsel oluşturmak için şuraya gönderilmesini kabul ediyorum:",
"Ich darf dieses Foto verwenden und stimme zu, dass Foto und Prompt an {x} übertragen werden.": "Bu fotoğrafı kullanma hakkım var ve fotoğraf ile istemin {x} hizmetine gönderilmesini kabul ediyorum.",
"Ich erstelle das Porträt mit KI": "Portreyi yapay zekâyla oluşturuyorum",
"Ich habe die AGB gelesen und akzeptiere sie. Ich buche als Unternehmer.": "Kullanım Koşullarını okudum ve kabul ediyorum. İşletme olarak satın alıyorum.",
