"Ihr Firmenlogo aus „Meine Lizenzen“ → „Deine Werbung in der Galerie“.": "„Lisanslarım“ → „Galerideki reklamın“ bölümündeki firma logon.",
"Ihre E-Mail-Adresse ist noch nicht bestätigt. Bitte klicken Sie auf den Link in unserer Mail – auch im Spam-Ordner nachsehen. Der Link gilt nur eine begrenzte Zeit.": "E-posta adresin henüz onaylanmadı. Lütfen e-postamızdaki bağlantıya tıkla – spam klasörüne de bak. Bağlantı yalnızca sınırlı süre geçerlidir.",
