"im Dashboard von Photobox Memories": "Photobox Memories panelinde",
"Im Druckfenster als Ziel „Als PDF speichern“ wählen – die Größe ist schon eingestellt.": "Yazdırma penceresinde hedef olarak “PDF olarak kaydet”i seçin – boyut zaten ayarlı.",
"Im Druckfenster als Ziel „Als PDF speichern“ wählen – die Größe ist schon eingestellt. Die Originalgröße ist für eine Druckerei (z. B. Forex- oder Kapa-Platte), die A4-Blätter zum Zusammenkleben. Jedes Feld ist genau so groß wie eine Kachel.": "Yazdırma penceresinde hedef olarak “PDF olarak kaydet”i seçin – boyut zaten ayarlı. Orijinal boyut matbaa içindir (ör. Forex veya foam board), A4 sayfalar birleştirmek içindir. Her alan tam olarak bir parça boyutundadır.",
"Im laufenden Mosaik sind schon {x} Felder belegt. Mit diesem Hauptbild bzw. Raster beginnt ein neues Mosaik (das bisherige bleibt gespeichert, falls du zurückstellst). Fortfahren?": "Çalışan mozaikte zaten {x} alan dolu. Bu ana görsel veya ızgarayla yeni bir mozaik başlar (geri dönersen önceki kayıtlı kalır). Devam edilsin mi?",
