"Im Tarif Kostenlos zeigen die Fotobox und die Gäste-Seiten das Logo und die Werbung von Photobox Memories. Ab Basis erscheint hier deine eigene.": "Ücretsiz planda fotoğraf kabini ve misafir sayfaları Photobox Memories’in logosunu ve reklamını gösterir. Basic’ten itibaren burada kendi reklamın görünür.",
"Im Tarif Pro sind alle Funktionen dabei: GIF, Boomerang und Video, Filter und Schönheitsfilter, Hintergrund entfernen, Virtueller Berater, eigene Vorlagen und Bildschirme, Umfrage und mehr.": "Pro planında tüm özellikler var: GIF, boomerang ve video, filtreler ve güzellik filtresi, arka plan kaldırma, sanal asistan, kendi şablonlar ve ekranlar, anket ve daha fazlası.",
