"In der kostenlosen Version zeigen die Fotobox und die Gäste-Seiten das Logo und die Werbung von Photobox Memories. Mit dem Fotobox-Abo erscheint hier deine eigene.": "Ücretsiz sürümde fotoğraf kabini ve misafir sayfaları Photobox Memories’in logosunu ve reklamını gösterir. Fotoğraf kabini aboneliğiyle burada kendi logon ve reklamın görünür.",
"In der Mitte der Startanimation ist eine weiße Scheibe – dort steht Ihr Logo. Die Vorschau zeigt es genau so wie auf der Fotobox.": "Başlangıç animasyonunun ortasında beyaz bir disk var – logon orada yer alır. Önizleme onu fotoğraf kabinindekiyle birebir aynı gösterir.",
