"Jede Feier ist ein eigenes Ereignis mit eigenen Einstellungen und eigener Galerie.": "Her kutlama kendi ayarları ve galerisi olan ayrı bir etkinliktir.",
"Jede FotoBox erscheint hier, sobald sie mit einem Lizenzschlüssel aktiviert wurde. Weise ein Event zu – die Box übernimmt die Einstellungen innerhalb einer Minute.": "Her kabin bir lisans anahtarıyla etkinleştirilir etkinleştirilmez burada görünür. Bir etkinlik ata – kabin ayarları bir dakika içinde alır.",
"Jede Änderung, die du als Betreiber an Daten deiner Kunden machst (Lizenzen, Zusatzfunktionen, Fotoboxen, Speicher, Guthaben, Tarife, Passwörter, Mails), und jede Admin-Anmeldung. Die letzten 200 Einträge.": "İşletmeci olarak müşterilerinin verilerinde yaptığın her değişiklik (lisanslar, ek özellikler, fotoğraf kabinleri, depolama, kredi, tarifeler, şifreler, e-postalar) ve her yönetici girişi. Son 200 kayıt.",
"Jeder mit dem Link zum Ereignis darf dieses Ereignis sehen": "Etkinlik bağlantısına sahip herkes bu etkinliği görebilir",
"Jedes Foto automatisch": "Her fotoğraf otomatik",
"Jedes Foto vorher freigeben": "Her fotoğrafı önce onayla",
"Jedes Foto wird von der KI zur Karikatur – und danach vor allen Gästen Strich für Strich gezeichnet und eingefärbt, auf dem Bildschirm der Fotobox und auf dem zweiten Bildschirm (Fernseher/Beamer). Danach geht es wie gewohnt weiter: Drucken, QR-Code, Galerie. Kosten je nach Bildqualität: 1 KI-Credit pro Foto (1K) oder 2 Credits (2K), zentrale KI von Photobox Memories. Ist die Live-Karikatur an, entfällt die Stilauswahl der KI-Porträts.": "Yapay zekâ her fotoğrafı bir karikatüre dönüştürür – ardından tüm misafirlerin önünde, fotoğraf kabininin ekranında ve ikinci ekranda (TV/projektör) çizgi çizgi çizilip boyanır. Sonrasında her şey her zamanki gibi devam eder: baskı, QR kodu, galeri. Görüntü kalitesine göre maliyet: fotoğraf başına 1 yapay zekâ kredisi (1K) veya 2 kredi (2K), Photobox Memories’in merkezi yapay zekâsı. Canlı karikatür açıkken yapay zekâ portrelerinin stil seçimi atlanır.",
"Jedes Foto wird von der KI zur Karikatur – und danach vor allen Gästen Strich für Strich gezeichnet und eingefärbt, auf dem Bildschirm der Fotobox und auf dem zweiten Bildschirm (Fernseher/Beamer). Danach geht es wie gewohnt weiter: Drucken, QR-Code, Galerie. Kosten: 1 KI-Credit pro Foto (zentrale KI von Photobox Memories). Ist die Live-Karikatur an, entfällt die Stilauswahl der KI-Porträts.": "Her fotoğraf yapay zekâ ile karikatüre dönüşür – ardından tüm misafirlerin önünde, fotoğraf kabininin ekranında ve ikinci ekranda (TV/projektör) çizgi çizgi çizilip boyanır. Sonra her şey her zamanki gibi devam eder: yazdır, QR kod, galeri. Maliyet: fotoğraf başına 1 yapay zekâ kredisi (Photobox Memories merkezi yapay zekâsı). Canlı karikatür açıkken yapay zekâ portrelerinin stil seçimi atlanır.",
"Jedes Foto wird zur Karikatur und live Strich für Strich gezeichnet – auch per Selfie vom Handy.": "Her fotoğraf karikatüre dönüşür ve canlı olarak çizgi çizgi çizilir – telefondan özçekimle de.",
"Jedes Foto wird zur Karikatur – live gezeichnet vor allen Gästen": "Her fotoğraf karikatüre dönüşür – tüm misafirlerin önünde canlı çizilir",
"Jedes Foto wird zur Karikatur – live Strich für Strich gezeichnet, an der Fotobox und per Selfie vom Handy.": "Her fotoğraf karikatüre dönüşür – fotoğraf kabininde ve telefondan selfie ile canlı olarak çizgi çizgi çizilir.",
"Jedes KI-Bild braucht Credits. Den Stand siehst du auf der KI-Seite, aufladen kannst du im Dashboard unter „Meine Lizenzen“.": "Her yapay zeka resmi kredi gerektirir. Bakiyeyi yapay zeka sayfasında görürsün, panelde „Lisanslarım“ altında yükleyebilirsin.",
