"Kostenlos: Fotobox-Funktionen mit Logo und Werbung von Photobox Memories. Basis: Fotobox-Funktionen mit deinem eigenen Logo. Pro: alle Funktionen. Was es erst ab Pro gibt, trägt ein Schloss. Buchen im Online-Dashboard unter „Meine Lizenzen“.": "Ücretsiz: Photobox Memories logosu ve reklamıyla fotoğraf kabini özellikleri. Basic: kendi logonla fotoğraf kabini özellikleri. Pro: tüm özellikler. Yalnızca Pro’da olanlarda kilit var. Çevrimiçi panelde „Lisanslarım“ altında al.",
