"laufen": "aktif",
"Laufende Abos bei Stripe (auch der BoothDesigner) kosten ab der nächsten Rechnung 0 €.": "Stripe’taki devam eden abonelikler (BoothDesigner dahil) bir sonraki faturadan itibaren 0 €.",
"Laufende Abos bei Stripe (auch der BoothDesigner) kosten mit VIP ab der nächsten Rechnung 0 €. Beim Ausschalten gilt dort wieder der normale Preis bzw. sein Rabatt.": "VIP ile Stripe’taki devam eden abonelikler (BoothDesigner dahil) bir sonraki faturadan itibaren 0 €. Kapatıldığında yeniden normal fiyat veya müşterinin indirimi geçerli olur.",
"Laufende Abos bei Stripe kosten ab der nächsten Rechnung 0 € (der BoothDesigner bleibt kostenpflichtig).": "Stripe’daki aktif abonelikler bir sonraki faturadan itibaren 0 € tutar (BoothDesigner ücretli kalır).",
"Laufende Abos bei Stripe kosten ab der nächsten Rechnung wieder den normalen Preis (bzw. mit seinem Rabatt).": "Stripe’daki aktif abonelikler bir sonraki faturadan itibaren yeniden normal fiyattan ücretlendirilir (ya da müşterinin indirimiyle).",
"Laufende Abos bei Stripe kosten mit VIP ab der nächsten Rechnung 0 € (der BoothDesigner bleibt kostenpflichtig). Beim Ausschalten gilt dort wieder der normale Preis bzw. sein Rabatt.": "VIP ile Stripe’daki aktif abonelikler bir sonraki faturadan itibaren 0 € tutar (BoothDesigner ücretli kalır). Kapatıldığında orada yeniden normal fiyat ya da müşterinin indirimi geçerli olur.",
"Laufende Abos bei Stripe werden beim Speichern von Rabatt und VIP automatisch angepasst (ab der nächsten Rechnung). „Bei Stripe übernehmen“ wiederholt das, falls es nicht geklappt hat.": "Stripe’daki aktif abonelikler, indirim ve VIP kaydedildiğinde otomatik olarak ayarlanır (bir sonraki faturadan itibaren). İşe yaramadıysa “Stripe’da uygula” bunu tekrarlar.",
"Laufende Abos bei Stripe ändert VIP nicht – sie werden weiter abgebucht. Soll der Kunde nichts mehr zahlen, das Abo bei Stripe kündigen.": "VIP, Stripe’daki aktif abonelikleri değiştirmez – ödeme alınmaya devam eder. Müşterinin artık hiçbir şey ödememesi gerekiyorsa aboneliği Stripe’da iptal et.",
