"Mit deinem Konto anmelden und den Lizenzschlüssel eintragen – nötig für Online-Galerie, QR-Code und KI.": "Hesabınla oturum aç ve lisans anahtarını gir – çevrimiçi galeri, QR kodu ve yapay zeka için gerekli.",
