"Mit dem neuesten Foto dieses Ereignisses": "Bu etkinliğin en yeni fotoğrafıyla",
"Mit dem Online-Dashboard kannst du deine Fotobox vom Handy oder Computer aus sehen und steuern: Zahl der Ausdrucke, Status von Kamera und Drucker, Testdruck auslösen und Kamerawerte einstellen. Im Dashboard unter „Geräte“.": "Çevrimiçi panelle kabinini telefondan veya bilgisayardan görebilir ve kontrol edebilirsin: baskı sayısı, kamera ve yazıcı durumu, test baskısı ve kamera değerleri. Panelde “Cihazlar” altında.",
"Mit dem Schlüssel, den du beim Einrichten aufgeschrieben hast, richtest du die App auf dem neuen Handy wieder ein (in der App „+“ → Schlüssel eingeben). Ohne Schlüssel: in Supabase unter Authentication → Users dein Konto öffnen und den Faktor bei „Multi-Factor Authentication“ löschen – danach richtest du die App hier neu ein.": "Kurulumda not aldığın anahtarla uygulamayı yeni telefonda yeniden kurarsın (uygulamada “+” → anahtarı gir). Anahtar yoksa: Supabase'de Authentication → Users altında hesabını aç ve “Multi-Factor Authentication” bölümündeki faktörü sil – sonra uygulamayı burada yeniden kur.",
"Mit dem Testfoto eine Karikatur erstellen und die Live-Zeichnung ansehen. Das Testfoto änderst du unter KI-Porträts.": "Test fotoğrafıyla bir karikatür oluştur ve canlı çizimi izle. Test fotoğrafını Yapay zekâ portreleri altında değiştirirsin.",
"Mit der Kamera-App aufnehmen": "Kamera uygulamasıyla kaydet",
"Mit der Maus verschieben · Strg + Mausrad zoomt": "Fareyle kaydır · Ctrl + fare tekerleği yakınlaştırır",
"Mit der Photobox Cloud kannst du deine Eventfotos teilen und versenden. Du erhältst eine eigene Galerie-Seite für deine Kunden – mit Passwortschutz und „Alle herunterladen“.": "Photobox Cloud ile etkinlik fotoğraflarını paylaşabilir ve gönderebilirsin. Müşterilerin için şifre korumalı ve “Tümünü indir” özellikli kendi galeri sayfanı alırsın.",
"Mit diesem Konto anmelden": "Bu hesapla giriş yap",
"Mit eigener Gestaltung gelten „Speicherort der Teilen-Symbole“ und „Textetiketten“ nicht mehr – alles steht dort, wo du es hinschiebst.": "Kendi tasarımınızla „Paylaşım simgelerinin yeri“ ve „Metin etiketleri“ artık geçerli değildir – her şey sürüklediğiniz yerde durur.",
"Mit einem Beispielfoto": "Örnek bir fotoğrafla",
"Mit einem Finger verschieben · mit zwei Fingern zoomen": "Tek parmakla kaydır · iki parmakla yakınlaştır",
"Mit einem PIN kommen Gäste nicht ins Menü. „Sperren“ auf der Startseite sperrt die Fotobox sofort.": "PIN ile misafirler menüye giremez. Ana sayfadaki „Kilitle“ fotoğraf kabinini hemen kilitler.",
