"Nach der Verarbeitung": "İşlemden sonra",
"Nach jedem Bau kommt die neue Version von selbst in den Download-Bereich – „Neueste Version herunterladen“ unter „Geräte“ bietet immer die neueste an. Von Hand nur nötig, wenn das einmal nicht geklappt hat: Installationsdatei": "Her derlemeden sonra yeni sürüm kendiliğinden indirme alanına gelir – „Cihazlar“ altındaki „En yeni sürümü indir“ her zaman en yenisini sunar. Elle yalnızca bu bir kez işe yaramazsa gerekir: Kurulum dosyasını",
