"Nach Änderungen (z. B. Feldnummern oder Größe der Nummer) neu starten: Alle Felder werden leer und jede neue Kachel bekommt die aktuellen Einstellungen. Die Fotos bleiben in der Galerie. Danach die Tafel neu drucken. Geht auch im Dashboard.": "Değişikliklerden sonra (ör. alan numaraları veya numara boyutu) yeniden başlat: Tüm alanlar boşalır ve her yeni parça güncel ayarları alır. Fotoğraflar galeride kalır. Ardından panoyu yeniden yazdır. Kontrol panelinden de yapılabilir.",
