"Nur fürs Livebild – das Foto behält seine Werte. Zu dunkel? Längere Verschlusszeit (z. B. 1/30 statt 1/200) und höhere ISO (z. B. 1600) wählen. Die Kamera muss dafür auf M (manuell) stehen.": "Yalnızca canlı görüntü için – fotoğraf kendi değerlerini korur. Çok mu karanlık? Daha uzun enstantane (ör. 1/200 yerine 1/30) ve daha yüksek ISO (ör. 1600) seç. Kamera bunun için M (manuel) konumunda olmalı.",
