"Preise pro Fotobox inkl. MwSt. Bezahlung sicher über Stripe. Die Lizenz wird direkt nach der Zahlung freigeschaltet – eine Testlizenz läuft dabei einfach weiter.": "Fiyatlar kabin başına, KDV dahil. Stripe ile güvenli ödeme. Lisans ödemeden hemen sonra etkinleşir – deneme lisansı kesintisiz devam eder.",
"Preise pro Fotobox, brutto. Kunden sehen nur eingeschaltete Tarife unter „Meine Lizenzen“ und kaufen über Stripe – die Lizenz entsteht nach der Zahlung von selbst. Abos verlängern sich automatisch; gekündigte laufen bis zum Ende der bezahlten Zeit.": "Fiyatlar kabin başına, brüt. Müşteriler yalnızca açık tarifeleri “Lisanslarım” altında görür ve Stripe ile satın alır – lisans ödemeden sonra kendiliğinden oluşur. Abonelikler otomatik yenilenir; iptal edilenler ödenen sürenin sonuna kadar çalışır.",
