"Öffnet das Studio im Admin-Modus: Design und Format wählen, im erweiterten Modus Texte, Deko und Fotofelder anpassen, unten „Für dieses Format speichern“. Alle Kunden sehen danach die korrigierte Fassung; eingetippte Texte bleiben.": "Studio’yu yönetici modunda açar: Tasarım ve format seç, gelişmiş modda metinleri, süslemeleri ve fotoğraf alanlarını düzenle, en altta “Bu format için kaydet”e tıkla. Ardından tüm müşteriler düzeltilmiş sürümü görür; yazılmış metinler korunur.",
"Ölgemälde": "Yağlı boya",
"Ölgemälde.": "Yağlı boya.",
"über": "üstünde",
"Über 100 Designs für Hochzeit, Geburtstag, Taufe, Firmenfeier und mehr – auf deiner eigenen Webseite, mit deinem Logo und deinen Farben. Deine Kunden tragen Namen und Datum ein, passen das Design an und schicken es ab. Du bekommst eine Mail und übernimmst das Design mit einem Klick als Fotolayout in dein Ereignis.": "Düğün, doğum günü, vaftiz, şirket etkinliği ve daha fazlası için 100’den fazla tasarım – kendi web sitende, kendi logon ve renklerinle. Müşterilerin isimleri ve tarihi girer, tasarımı uyarlar ve gönderir. Sana bir e-posta gelir ve tasarımı tek tıkla fotoğraf düzeni olarak etkinliğine eklersin.",
